label("$C$",(0.3,-0.94),SSE);
dot((0.3,-0.94));
label("$D$",(-0.7,-0.7),SW);
dot((-0.7,-0.7));
dot((0.23,-0.7));
label("$P$",(0.23,-0.7),NE);

